/* Universal CSS */

:root {
    --main-red-color: #b91c1c;

    /* Light Mode */
    --bg-white-color: #fff8f6;
    --secundary-bg-white-color: #f5edeb;
    --black-text-color: #1f2937;
    --secundary-black-text-color: #6b7280;

    /* Dark Mode */
    --bg-dark-mode: #1F1F1E;
    --secundary-bg-dark-mode: #2C2C2B;
    --white-text-color: #f9fafb;

    /* Weitere Farben */
    --orange-color: #d97706;
    --brown-red-color: #7c2d12;
    --green-color: #3A7D44;

    --detail-font-size-title: 2.75rem;
    --detail-font-size-content: 1.25rem;
}

* {
    box-sizing: border-box;
}

body {
    transition: background-color 0.4s ease, color 0.4s ease;
    margin: 0;
    background-color: var(--bg-white-color);
}


/* Dark Mode CSS */

body.dark-mode {
    background-color: var(--bg-dark-mode);
    color: var(--white-text-color);
}

body.dark-mode .card1 {
    background-color: var(--secundary-bg-dark-mode);
    color: var(--white-text-color);
}

body.dark-mode .hero-card {
    background-color: var(--secundary-bg-dark-mode);
    color: var(--white-text-color);
}

body.dark-mode .hero-body h2 {
    color: var(--white-text-color);
}

body.dark-mode .hero-body p {
    color: var(--secundary-bg-white-color);
}

body.dark-mode .card-body h2 {
    color: var(--white-text-color);
}

body.dark-mode .card-body p {
    color: var(--secundary-bg-white-color);
}

body.dark-mode .pop-up-card {
    background-color: var(--secundary-bg-dark-mode);
}

body.dark-mode input,
body.dark-mode textarea {
    background-color: var(--bg-dark-mode);
    color: var(--white-text-color);
    border-color: var(--secundary-black-text-color);
}

body.dark-mode .detail-container {
    background-color: var(--secundary-bg-dark-mode);
}

body.dark-mode .detail-card-footer {
    background-color: color-mix(in srgb, var(--secundary-bg-dark-mode) 30%, transparent);
}


/* Header CSS */

header {
    display: block;
    unicode-bidi: isolate;
}

.header {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    background-color: var(--main-red-color);
    height: 80px;
    position: sticky;
    top: 0;
}

.header-content {
    display: flex;
    align-items: center;
    width: 66%;
    max-width: 100%;
    padding: 0 16px;
}

.headername {
    color: white;
    font-size: 23px;
    font-family: Verdana, sans-serif;
    cursor: pointer;
}

.darkmode-toggle {}

#new-post-button {
    background: none;
    color: white;
    border: white 1px solid;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.4s ease, color 0.4s ease;
    font-size: 17px;
    font-family: Verdana, sans-serif;
}

#new-post-button:hover {}

.toggle-spacer {
    flex-grow: 1;
}

/* Main Content CSS */

.main-content {
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
    width: 100%;
    height: 100%;
}

.top-spacer {
    height: 100px;
    width: 100%;
}

.header-content-spacer {
    height: 40px;
    width: 100%;
}

.entry-toggle-spacer {
    width: 40px;
}

/* Normale Karte CSS */

.card1 {
    transition: background-color 0.4s ease, color 0.4s ease;
    height: 350px;
    background-color: var(--secundary-bg-white-color);
    box-shadow: rgba(0, 0, 0, 0.35) 0 5px 15px;
    overflow: hidden;
}

.card1.dark-mode {
    background-color: var(--secundary-bg-dark-mode);
    color: var(--white-text-color);
}

.card-image {
    width: 100%;
    height: 200px;
    object-fit: cover;
    display: block;
}

.card-image-placeholder {
    background-color: #d1d5db;
}

.hero-image-wrapper {
    width: 60%;
    flex-shrink: 0;
    overflow: hidden;
}

.hero-image {
    width: 100%;
    height: 380px;
    object-fit: cover;
    object-position: center;
    display: block;
}

.hero-image-placeholder {
    background-color: #d1d5db;
}

.card-body {
    padding: 15px;
    font-family: Verdana, sans-serif;
}

.card-body h2 {
    font-size: 1.2rem;
    color: var(--black-text-color);
    border-bottom: 1px solid var(--secundary-black-text-color);
    padding-bottom: 10px;
}

.card-body p {
    font-size: 1rem;
    color: var(--secundary-black-text-color);
}

.grid-container {
    width: 85%;
    max-width: 100%;
}

#posts-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(400px, 100%), 1fr));
    width: 100%;
    grid-gap: 20px;
    cursor: pointer;
}

/* Hero Karte CSS */

.hero-container {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
    cursor: pointer;
}

.hero-card {
    display: flex;
    width: min(1000px, 95%);
    height: 380px;
    border-radius: 20px;
    background-color: var(--secundary-bg-white-color);
    box-shadow: rgba(0, 0, 0, 0.35) 0 5px 15px;
    transition: background-color 0.4s ease, color 0.4s ease;
    overflow: hidden;
}

.hero-card.dark-mode {
    background-color: var(--secundary-bg-dark-mode);
    color: var(--white-text-color);
}

/* Entfernt alten hero-image Block (bereits oben neu definiert) */

.hero-body {
    padding: 15px;
    font-family: Verdana, sans-serif;
}

.hero-body h2 {
    font-size: 1.6rem;
    color: var(--black-text-color);
    border-bottom: 1px solid var(--secundary-black-text-color);
    padding-bottom: 10px;
}

.hero-body p {
    font-size: 1.4rem;
    color: var(--secundary-black-text-color);
}

/* Pop-Up CSS */

.pop-up {
    width: 100%;
    position: fixed;
    z-index: 1;
}

.form-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.pop-up-card {
    display: flex;
    flex-direction: column;
    transition: background-color 0.4s ease, color 0.4s ease;
    width: min(50%, 600px);
    max-width: 95vw;
    height: auto;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 20px;
    background-color: var(--secundary-bg-white-color);
    box-shadow: rgba(0, 0, 0, 0.35) 0 5px 15px;
    padding: 20px;
}

.new-post-header {
    width: 100%;
    top: 0;
}

.new-post-header-title {
    font-size: 1.6rem;
    font-weight: bold;
    font-family: Veradana, sans-serif;
    top: 0;
    padding: 10px;
}

.pop-up-content {
    margin: auto 0;
}

.pop-up-footer {
    margin-left: auto;
    padding: 10px;
}

.label {
    font-size: 1.25rem;
    font-family: sans-serif;
    margin: 5px 0;
}

.input-field {
    font-family: sans-serif;
    font-size: 1rem;
    border: 1px solid var(--brown-red-color);
    border-radius: 5px;
    width: 100%;
    transition: background-color 0.4s ease, color 0.4s ease;
    resize: none;
}


/* Detail CSS */

.detail-hero-image {
    width: 83.333333%;
    max-height: 400px;
    object-fit: cover;
    border-radius: 12px;
    margin-top: 20px;
    margin-bottom: 10px;
    display: block;
}

.detail-main-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
}

.detail-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background-color: var(--secundary-bg-white-color);
    width: min(70%, 100%);
